def slopes(coeffs, x, h):
    def f(t):
        acc = 0.0
        for c in reversed(coeffs):          # Horner: c0 + t(c1 + t(c2 + ...))
            acc = acc * t + c
        return acc

    exact = sum(k * c * x ** (k - 1) for k, c in enumerate(coeffs) if k >= 1)
    fx, up, down = f(x), f(x + h), f(x - h)
    return {
        "forward": (up - fx) / h,
        "backward": (fx - down) / h,
        "central": (up - down) / (2 * h),
        "exact": float(exact),
    }
